$s=new Game();if(!$s->loggedIn){http_response_code(401);echo json_encode(['ok'=>false]);exit;}$db=$s->db_link;$uid=(int)$_SESSION['userid'];$db->query("CREATE TABLE IF NOT EXISTS game_email_messages (email_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,from_uid INT NULL,from_address VARCHAR(190) NOT NULL,to_uid INT NULL,to_address VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL,body TEXT NOT NULL,email_type VARCHAR(16) NOT NULL DEFAULT 'player',is_read TINYINT(1) NOT NULL DEFAULT 0,is_deleted TINYINT(1) NOT NULL DEFAULT 0,delivery_status VARCHAR(16) NOT NULL DEFAULT 'inbox',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,broadcast_id BIGINT UNSIGNED NULL,has_attachments TINYINT(1) NOT NULL DEFAULT 0,KEY idx_game_email_recipient(to_uid,is_deleted,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("ALTER TABLE game_email_messages ADD COLUMN IF NOT EXISTS broadcast_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS has_attachments TINYINT(1) NOT NULL DEFAULT 0");$countQ=$db->query("SELECT COUNT(*) total FROM game_email_messages WHERE to_uid=$uid AND is_read=0 AND is_deleted=0");$count=(int)($countQ?$countQ->fetch_assoc()['total']:0);$latestQ=$db->query("SELECT email_id,subject,email_type,created_at FROM game_email_messages WHERE to_uid=$uid AND is_read=0 AND is_deleted=0 ORDER BY email_id DESC LIMIT 1");$latest=$latestQ?$latestQ->fetch_assoc():null;echo json_encode(['ok'=>true,'unread'=>$count,'latest'=>$latest?:null],JSON_UNESCAPED_SLASHES);
